import java.awt.*;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.event.*;
import javax.swing.text.*;
import javax.swing.table.*;
import java.util.regex.*;

/** Native request workspace. Raw editors remain the source of truth. */
final class RequestWorkbench extends JPanel {
    final VulnApp app;
    final JLabel method=VulnTheme.label("GET",14,VulnTheme.GREEN),result=VulnTheme.label("No response",12,VulnTheme.MUTED);
    final JTextPane body=new JTextPane();
    final JTextArea headers=VulnApp.area(false);
    final DefaultTableModel requestHeaders=VulnApp.model("Name","Value"),params=VulnApp.model("Name","Value");
    final javax.swing.Timer update;
    long elapsed=-1; int responseBytes;
    void received(long millis,int bytes){elapsed=millis;responseBytes=bytes;update.restart();}
    RequestWorkbench(VulnApp app){super(new BorderLayout(0,14));this.app=app;setBorder(new EmptyBorder(18,20,0,20));
        JPanel address=new JPanel(new BorderLayout(12,0));JPanel field=new JPanel(new BorderLayout(12,0));field.setBorder(new CompoundBorder(new LineBorder(VulnTheme.BORDER),new EmptyBorder(3,12,3,4)));field.add(method,BorderLayout.WEST);app.repeaterUrl.setBorder(new EmptyBorder(8,0,8,8));app.repeaterUrl.setToolTipText("Origem HTTP/HTTPS. Caminho e query vêm da primeira linha do request.");field.add(app.repeaterUrl);address.add(field);app.send.setBackground(VulnTheme.ACCENT);app.send.setForeground(VulnTheme.CANVAS);app.send.setPreferredSize(new Dimension(100,46));app.send.addActionListener(e->app.sendRepeater());address.add(app.send,BorderLayout.EAST);add(address,BorderLayout.NORTH);
        app.repeaterRequest.setText(VulnApp.SAMPLE);
        RequestInspector requestTabs=new RequestInspector(app);
        JTabbedPane responseTabs=new JTabbedPane();body.setEditable(false);body.setBackground(VulnTheme.CANVAS);body.setForeground(VulnTheme.TEXT);body.setFont(new Font("Consolas",Font.PLAIN,14));body.setMargin(new Insets(18,16,18,16));responseTabs.addTab("Response",editor(body));responseTabs.addTab("Headers",editor(headers));responseTabs.addTab("Raw",editor(app.repeaterResponse));
        JPanel response=new JPanel(new BorderLayout());JPanel meta=new JPanel(new BorderLayout());meta.setBorder(new EmptyBorder(7,12,8,12));meta.add(VulnTheme.label("HTTP RESPONSE",10,VulnTheme.MUTED));meta.add(result,BorderLayout.EAST);response.add(meta,BorderLayout.NORTH);response.add(responseTabs);
        JPanel request=new JPanel(new BorderLayout());JLabel hint=VulnTheme.label("HTTP REQUEST   ·   first line defines path & query",10,VulnTheme.MUTED);hint.setBorder(new EmptyBorder(7,12,8,12));request.add(hint,BorderLayout.NORTH);request.add(requestTabs);
        JSplitPane panes=VulnApp.split(JSplitPane.HORIZONTAL_SPLIT,request,response,.46);panes.setDividerLocation(.46);add(panes);
        update=new javax.swing.Timer(100,e->refresh());update.setRepeats(false);DocumentListener watch=new DocumentListener(){public void insertUpdate(DocumentEvent e){update.restart();}public void removeUpdate(DocumentEvent e){update.restart();}public void changedUpdate(DocumentEvent e){}};app.repeaterRequest.getDocument().addDocumentListener(watch);app.repeaterResponse.getDocument().addDocumentListener(watch);refresh();
        app.addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){update.stop();}});
    }
    static JComponent table(DefaultTableModel model,String hint){JPanel p=new JPanel(new BorderLayout(0,16));p.setBorder(new EmptyBorder(18,12,12,12));p.add(VulnTheme.label(hint,12,VulnTheme.MUTED),BorderLayout.NORTH);JTable table=new JTable(model);table.setFillsViewportHeight(true);table.setShowVerticalLines(true);p.add(new JScrollPane(table));return p;}
    static JScrollPane editor(JTextComponent text){JScrollPane scroll=new JScrollPane(text);scroll.setBorder(null);JTextArea lines=new JTextArea("1");lines.setEditable(false);lines.setFocusable(false);lines.setFont(text.getFont());lines.setForeground(VulnTheme.MUTED);lines.setBackground(VulnTheme.CANVAS);Insets m=text.getMargin();lines.setMargin(new Insets(m.top,12,m.bottom,10));scroll.setRowHeaderView(lines);Runnable number=()->{int count=Math.min(10000,text.getDocument().getDefaultRootElement().getElementCount());StringBuilder b=new StringBuilder();for(int i=1;i<=count;i++)b.append(i).append('\n');lines.setText(b.toString());};text.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){number.run();}public void removeUpdate(DocumentEvent e){number.run();}public void changedUpdate(DocumentEvent e){}});number.run();return scroll;}
    void refresh(){String raw=app.repeaterRequest.getText();String[] rows=raw.split("\\r?\\n");method.setText(rows.length==0?"HTTP":rows[0].split(" ",2)[0]);requestHeaders.setRowCount(0);for(int i=1;i<rows.length&&!rows[i].isEmpty();i++){int at=rows[i].indexOf(':');if(at>0)requestHeaders.addRow(new Object[]{rows[i].substring(0,at),rows[i].substring(at+1).strip()});}params.setRowCount(0);if(rows.length>0){String[] first=rows[0].split(" ");if(first.length>1){int q=first[1].indexOf('?');if(q>=0)for(String item:first[1].substring(q+1).split("&")){String[] pair=item.split("=",2);params.addRow(new Object[]{pair[0],pair.length>1?pair[1]:""});}}}
        String response=app.repeaterResponse.getText();int boundary=response.indexOf("\r\n\r\n");headers.setText(boundary<0?"":response.substring(0,boundary));headers.setCaretPosition(0);String content=boundary<0?response:response.substring(boundary+4);boolean json=boundary>=0&&response.substring(0,boundary).toLowerCase(java.util.Locale.ROOT).contains("json");body.setText(json&&content.length()<262144?pretty(content):content);body.setCaretPosition(0);if(json&&body.getDocument().getLength()<262144)highlight();
        if(response.startsWith("HTTP/")){String first=response.split("\\r?\\n",2)[0];result.setText(first.replaceFirst("HTTP/[^ ]+ ","")+(elapsed<0?"":"   "+elapsed+" ms   "+responseBytes+" B"));result.setForeground(first.matches("HTTP/[^ ]+ [23].*")?VulnTheme.GREEN:VulnTheme.ACCENT);}else{result.setText(response.startsWith("Sending")?"Sending…":response.startsWith("Request failed")?"Request failed":"No response");result.setForeground(VulnTheme.MUTED);}
    }
    static String pretty(String json){StringBuilder out=new StringBuilder();int indent=0;boolean quoted=false,escaped=false;for(int i=0;i<json.length();i++){char c=json.charAt(i);if(quoted){out.append(c);if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c=='"')quoted=false;continue;}switch(c){case '"'-> {quoted=true;out.append(c);}case '{','['->{out.append(c).append('\n');indent++;out.append("  ".repeat(Math.min(indent,64)));}case '}',']'->{indent=Math.max(0,indent-1);out.append('\n').append("  ".repeat(Math.min(indent,64))).append(c);}case ','->out.append(c).append('\n').append("  ".repeat(Math.min(indent,64)));case ':'->out.append(": ");default->{if(!Character.isWhitespace(c))out.append(c);}}}return out.toString();}
    void highlight(){StyledDocument doc=body.getStyledDocument();SimpleAttributeSet base=new SimpleAttributeSet();StyleConstants.setForeground(base,VulnTheme.TEXT);doc.setCharacterAttributes(0,doc.getLength(),base,true);String text=body.getText();Matcher m=Pattern.compile("\"(?:\\\\.|[^\"\\\\])*\"|\\b(?:true|false|null|-?\\d+(?:\\.\\d+)?)\\b").matcher(text);while(m.find()){Color color;if(m.group().startsWith("\"")){int after=m.end();while(after<text.length()&&Character.isWhitespace(text.charAt(after)))after++;color=after<text.length()&&text.charAt(after)==':'?VulnTheme.BLUE:new Color(0xD6BC8D);}else color=new Color(0xC99ACB);SimpleAttributeSet style=new SimpleAttributeSet();StyleConstants.setForeground(style,color);doc.setCharacterAttributes(m.start(),m.end()-m.start(),style,true);}}
}
